import { Component, ChangeDetectionStrategy, input, output, computed } from '@angular/core';

const SIZE_MAP: Record<'sm' | 'md' | 'lg', string> = {
  sm: 'px-md py-xs text-sm',
  md: 'px-lg py-sm text-md', // token sizes: lg = 24px, sm = 8px, font-size-md = 16px
  lg: 'px-xl py-md text-lg'
};

const VARIANT_MAP: Record<'primary' | 'outline' | 'error', string> = {
  primary: `
    bg-primary text-text-inverse
    hover:bg-primary hover:text-accent hover:shadow-[0_2px_2px_0_var(--color-accent)]
    active:bg-accent active:text-primary active:border-primary
  `,
  outline: `
    bg-bg-default text-text-primary
    hover:bg-bg-default hover:border-accent hover:text-accent hover:shadow-[0_2px_2px_0_var(--color-accent)]
    active:bg-bg-default active:border-accent active:text-accent
  `,
  error: `
    bg-error text-text-inverse
    hover:bg-primary hover:border-primary hover:text-error hover:shadow-[0_2px_2px_0_var(--color-error)]
    active:bg-error active:border-error active:text-text-inverse
  `
};

@Component({
  selector: 'app-button',
  standalone: true,
  templateUrl: './button.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ButtonComponent {
  variant = input<'primary' | 'outline' | 'error'>('primary');
  size = input<'sm' | 'md' | 'lg'>('md');
  disabled = input(false);
  type = input<'button' | 'submit' | 'reset'>('button');
  ariaLabel = input<string>();

  clicked = output<MouseEvent>();

  /**
   * @ignore
   * Handles the click event on the button.
   * @param event Event
   */
  onClick(event: MouseEvent) {
    if (!this.disabled()) {
      this.clicked.emit(event);
    }
  }

  /**
   * @ignore
   * Computes the CSS classes for the button based on its variant and size.
   */
  buttonClasses = computed(() => {
    const s = this.size();
    const sizeClasses = SIZE_MAP[s] || SIZE_MAP.md;

    const v = this.variant();
    const variantClasses = VARIANT_MAP[v] || VARIANT_MAP.primary;

    return `${sizeClasses} ${variantClasses}`;
  });
}

import { ChangeDetectionStrategy, Component, input, output } from '@angular/core';
import { FaIconComponent } from '@fortawesome/angular-fontawesome';
import { faSquare } from '@fortawesome/free-regular-svg-icons';
import { faSquareCheck } from '@fortawesome/free-solid-svg-icons';

@Component({
  selector: 'app-checkbox',
  imports: [FaIconComponent],
  templateUrl: './checkbox.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CheckboxComponent {
  checked = input<boolean>(false);
  disabled = input<boolean>(false);
  ariaLabel = input<string | undefined>(undefined);

  /**
   * Event emitted when the checkbox state changes.
   */
  checkedChange = output<boolean>();

  /**
   * @ignore
   * Unchecked state icon.
   */
  readonly faSquare = faSquare;

  /**
   * @ignore
   * Checked state icon.
   */
  readonly faSquareCheck = faSquareCheck;

  /**
   * @ignore
   * Handles the native change event and emits the new state.
   * @param event Event
   */
  onCheckChange(event: Event): void {
    const target = event.target as HTMLInputElement;
    this.checkedChange.emit(target.checked);
  }
}

import {
  Component,
  ChangeDetectionStrategy,
  input,
  output,
  effect,
  ElementRef,
  viewChild,
} from '@angular/core';
import { FaIconComponent } from '@fortawesome/angular-fontawesome';
import { faXmark } from '@fortawesome/free-solid-svg-icons';
import { ButtonComponent } from '../button/button.component';

@Component({
  selector: 'app-delete-task-modal',
  standalone: true,
  imports: [ButtonComponent, FaIconComponent],
  templateUrl: './delete-task-modal.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DeleteTaskModalComponent {
  isOpen = input<boolean>(false);
  taskId = input.required<number>();

  confirmDelete = output<number>();
  closed = output<void>();

  /**
   * @ignore
   * References to the dialog elements for controlling visibility.
   */
  dialogRef = viewChild<ElementRef<HTMLDialogElement>>('dialogRef');

  /**
   * @ignore
   * References to the cancel button elements for controlling focus wrapper.
   */
  cancelBtnRef = viewChild('cancelBtnRef', { read: ElementRef });

  readonly faXmark = faXmark;

  constructor() {
    effect(() => {
      const dialog = this.dialogRef()?.nativeElement;
      if (dialog) {
        if (this.isOpen()) {
          dialog.showModal();
          setTimeout(() => {
            const cancelWrapper = this.cancelBtnRef()?.nativeElement;
            const button = cancelWrapper?.querySelector('button');
            if (button) {
              button.focus();
            } else {
              cancelWrapper?.focus();
            }
          }, 50);
        } else {
          dialog.close();
        }
      }
    });
  }

  onClose() {
    this.closed.emit();
  }

  onBackdropClick(event: MouseEvent) {
    const dialog = this.dialogRef()?.nativeElement;
    // If the click is precisely on the dialog element it's a backdrop click.
    if (dialog && event.target === dialog) {
      this.onClose();
    }
  }

  onConfirmDelete() {
    this.confirmDelete.emit(this.taskId());
    this.onClose();
  }
}

