import { Component, input, output, ChangeDetectionStrategy } from '@angular/core';
import { FaIconComponent } from '@fortawesome/angular-fontawesome';
import {
  faListCheck,
  faInbox,
  faCalendarDay,
  faCalendarWeek
} from '@fortawesome/free-solid-svg-icons';

export type ViewType = 'inbox' | 'today' | 'completed';

export type NavCounts = Partial<Record<ViewType, number>>;

@Component({
  selector: 'app-side-menu',
  standalone: true,
  imports: [FaIconComponent],
  templateUrl: './side-menu.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    'class': 'block h-full w-[250px] bg-springwood-100 overflow-clip border-r border-springwood-200'
  }
})
export class SideMenuComponent {
  activeView = input.required<ViewType>();
  navCounts = input<NavCounts>({ inbox: 0, today: 0, completed: 0 });

  navItemClick = output<ViewType>();

  icons = {
    logo: faListCheck,
    inbox: faInbox,
    today: faCalendarDay,
    completed: faCalendarWeek
  };

  menuItems: { id: ViewType; label: string; icon: any }[] = [
    { id: 'inbox', label: 'Inbox', icon: this.icons.inbox },
    { id: 'today', label: 'Today', icon: this.icons.today },
    { id: 'completed', label: 'Completed', icon: this.icons.completed }
  ];
}

import { ChangeDetectionStrategy, Component, input, output } from '@angular/core';
import { FaIconComponent } from '@fortawesome/angular-fontawesome';
import { faTrash } from '@fortawesome/free-solid-svg-icons';
import { CheckboxComponent } from '../checkbox/checkbox.component';
import { Task } from '../../models/task.model';

@Component({
  selector: 'app-task-item',
  imports: [FaIconComponent, CheckboxComponent],
  templateUrl: './task-item.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    class: 'block w-full',
  },
})
export class TaskItem {
  task = input.required<Task>();

  taskToggle = output<Task>();
  taskDelete = output<Task>();

  readonly faTrash = faTrash;

  toggleTask(checked: boolean): void {
    this.task().completed = checked;
    this.taskToggle.emit(this.task());
  }

  deleteTask(): void {
    this.taskDelete.emit(this.task());
  }
}

import { Component, ChangeDetectionStrategy, input, output } from '@angular/core';
import { Task } from '../../models/task.model';
import { TaskItem } from '../task-item/task-item.component';

@Component({
  selector: 'app-task-list',
  imports: [TaskItem],
  templateUrl: './task-list.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class TaskListComponent {
  title = input.required<string>();
  tasks = input.required<Task[]>();

  taskToggle = output<number>();
  taskDelete = output<number>();

  onTaskToggle(task: Task): void {
    this.taskToggle.emit(task.id);
  }

  onTaskDelete(task: Task): void {
    this.taskDelete.emit(task.id);
  }
}

